UPDATE T_BATCH_JOB
   SET JOB_STATUS      = 'RUNNING',
       LAST_START_DATE = #{startDate},
       LAST_START_TIME = #{startTime}
 WHERE PROC_NAME = #{procName}

UPDATE T_BATCH_JOB
   SET JOB_STATUS    = 'IDLE',
       LAST_END_DATE = #{endDate},
       LAST_END_TIME = #{endTime}
 WHERE PROC_NAME = #{procName}
